# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLASSROOM RULES &amp; IMPERATIVES (EMİR CÜMLELERİ VE KURALLAR)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Positive Imperatives (DOs - Yapılacaklar)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Raise your hand before speaking. (Parmak kaldır)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Listen to your teacher carefully. (Dikkatle dinle)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Tidy up your desk and keep it clean. (Sıranı topla)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Put the rubbish in the rubbish bin. (Çöpü kutuya at)</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Follow the classroom rules quietly. (Kurallara uy)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#166534">Fiilin yalın hâli (V1) cümlenin başında kullanılır.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Negative Imperatives (DON\'Ts - Yapılmayacaklar)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">• Don\'t shout in the classroom! (Sınıfta bağırma!)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">• Don\'t run in the corridors! (Koridorda koşma!)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">• Don\'t forget to bring your materials! (Unutma!)</text>\n  <text x="520" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">• Don\'t skip the lesson! (Dersi kaçırma / asma!)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">• Don\'t leave rubbish on the seat! (Çöp bırakma!)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#991b1b">Olumsuz emir için cümle «Don\'t + V1» ile başlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ASKING FOR PERMISSION (İZİN İSTEME) &amp; POLITE REQUESTS</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Can I / May I ...? (İzin İsteme)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• May I come in, please? (İçeri girebilir miyim?)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Can I borrow your dictionary? (Ödünç alabilir miyim?)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• May I clean the smartboard? (Tahtayı silebilir miyim?)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Can you lend me a rubber? (Bana silgi ödünç verir misin?)</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Can you give me your board marker? (Kalemi verir misin?)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#334155">Borrow: Ödünç almak  |  Lend: Ödünç vermek</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Giving &amp; Refusing Permission (Cevaplar)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">✔ Accepting (Kabul Etme):</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" fill="#14532d">• Yes, you can. / Yes, of course. (Evet, tabii ki.)</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" fill="#14532d">• Sure! Here you are. (Elbette! Buyur.)</text>\n  <text x="520" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">✘ Refusing (Kibarca Reddetme):</text>\n  <text x="520" y="192" text-anchor="middle" font-size="12" fill="#7f1d1d">• Sorry, not right now. (Üzgünüm, şu an olmaz.)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="12" fill="#7f1d1d">• I\'m sorry, I need it now. (Üzgünüm, şimdi bana lazım.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 2 REVISION: PRONOUNS, NUMBERS (50-100) &amp; SOCIAL EXPRESSIONS</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">Object Pronouns (Nesne Zamirleri)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">I ➔ me (bana/beni)</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">You ➔ you (sana/seni)</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">He ➔ him  |  She ➔ her</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">It ➔ it  |  We ➔ us</text>\n  <text x="125" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">They ➔ them (onlara/onları)</text>\n  <text x="125" y="210" text-anchor="middle" font-size="11" fill="#475569">«Give me a hand!» (Yardım et!)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Numbers 50 - 100 &amp; Adverbs</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">50: fifty  •  60: sixty  •  70: seventy</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">80: eighty  •  90: ninety  •  100: one hundred</text>\n  <text x="350" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Adverbs of Manner (Zarflar):</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11" fill="#1e40af">quietly (sessizce), loudly (yüksek sesle)</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11" fill="#1e40af">carefully (dikkatlice), slowly (yavaşça)</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" fill="#334155">There are sixty books on the bookshelf.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Social Language in Use</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Make the grade! (Başarılı ol!)</text>\n  <text x="575" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Don\'t skip the lesson! (Dersi kaçırma!)</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Give me a hand! (Bana yardım et!)</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• I don\'t feel all right. (İyi hissetmiyorum)</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Hold on! (Bekle!) / I\'d love to. (Çok isterim)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
